    { id = "human_minor_noble", name = "Younger child of a minor noble house",
      blurb = "My family has a name in Stormwind and not much else. The name went to my eldest sibling. I went looking for something of my own.",
      nudge = { trait = { cautious = 1 } }, home = "stormwind" },
    { id = "human_lordaeron_refugee", name = "Refugee from Lordaeron",
      blurb = "I was a child when we fled the plague and the dead. Stormwind took us in. I haven't forgotten the north.",
      nudge = { trait = { brave = 1 }, align = { light = 1 } } },
    { id = "human_paladin_squire", name = "Squire of the fallen Silver Hand", class = "PALADIN",
      blurb = "My training stopped when the Order fell apart. I kept the oaths anyway.",
      nudge = { trait = { pious = 1 }, align = { light = 2 } } },
    { id = "human_abbey_novice", name = "Novice of Northshire Abbey", class = "PRIEST",
      blurb = "The brothers of Northshire taught me my letters and my prayers in the same year. I've been trying to deserve both ever since.",
      nudge = { trait = { pious = 1 }, align = { light = 2, order = 1 } }, home = "northshire" },
    { id = "human_stonemason_child", name = "Child of the Stonemasons' Guild",
      blurb = "My father helped rebuild Stormwind and the nobles never paid him for it. Some of his friends went west in masks. He didn't, and he never stopped being angry about it.",
      nudge = { trait = { skeptical = 1 }, align = { order = -1 } }, home = "stormwind" },
    { id = "human_redridge_born", name = "Born in Lakeshire",
      blurb = "I grew up on the lake with the Redridge Mountains over every roof. When the orcs came down out of them, I learned how little the kingdom thinks about Lakeshire.",
      nudge = { trait = { brave = 1 } }, home = "lakeshire" },
    { id = "human_city_guard", name = "Former recruit of the Stormwind City Guard", class = "WARRIOR",
      blurb = "I walked the Trade District at night with a halberd and a lantern for two years. I left because the trouble was always somewhere else, and I wanted to go where it was.",
      nudge = { trait = { stern = 1 }, align = { order = 2 } }, home = "stormwind" },
    { id = "human_canal_pickpocket", name = "Pickpocket from the Stormwind canals", class = "ROGUE",
      blurb = "I learned to read purses before I could read words. Someone in Old Town noticed, and taught me there was better work than lifting coin off drunks.",
      nudge = { trait = { witty = 1 }, align = { honor = -2 } }, home = "stormwind" },
    { id = "human_mage_quarter", name = "Apprentice of the Mage Quarter", class = "MAGE",
      blurb = "My masters studied in Dalaran and never let me forget it. I learned more from their mistakes than their lectures, though I'd never tell them so.",
      nudge = { trait = { curious = 1 } }, home = "stormwind" },
    { id = "human_lamb_cellar", name = "Pupil from the Slaughtered Lamb's cellar", class = "WARLOCK",
      blurb = "Everyone in the Mage Quarter knows what goes on below the Slaughtered Lamb, and nobody talks about it. I went down the stairs once, out of curiosity, and kept going back.",
      nudge = { trait = { curious = 1 }, align = { light = -2 } }, home = "stormwind" },
    { id = "human_eastvale_woodsman", name = "Woodsman of Eastvale", class = "HUNTER",
      blurb = "I grew up felling pine in Eastvale and trailing wolves through it. Most humans want a sword; I wanted a bow and an animal that trusted me.",
      nudge = { trait = { cautious = 1 }, align = { order = -1 } }, home = "eastvale" },
    { id = "human_stromgarde_sellsword", name = "Sellsword out of Stromgarde", class = "WARRIOR",
      blurb = "I fought for Stromgarde against the Syndicate and the ogres of the Arathi Highlands. When the pay ran out the war didn't, so I came south to sell my sword where it would be paid for.",
      nudge = { trait = { greedy = 1 }, align = { honor = 1 } }, home = "refuge_pointe" },
    { id = "human_darkshire_watch", name = "Defender of Darkshire's walls", class = "PALADIN",
      blurb = "Darkshire's Night Watch taught me to hold a torch and a hammer at the same time. The Light came later, at the Cathedral, when I needed something stronger than either against what walks out of Raven Hill.",
      nudge = { trait = { stern = 1 }, align = { light = 1, order = 1 } }, home = "darkshire" },
    { id = "human_syndicate_runner", name = "Former runner for the Syndicate", class = "ROGUE",
      blurb = "I carried messages for the Syndicate between Southshore and the Alterac foothills. I learned enough of their business to know they would never let me quit, so I quit anyway and came south.",
      nudge = { trait = { cautious = 1 }, align = { honor = -1, order = -1 } }, home = "southshore" },
    { id = "human_sentinel_hill_healer", name = "Healer to the People's Militia", class = "PRIEST",
      blurb = "When the People's Militia gathered on Sentinel Hill, there was no priest to tend them, so I left the Cathedral with bandages and a prayer book. Gryan Stoutmantle's farmers taught me more about faith than any sermon did.",
      nudge = { trait = { generous = 1 }, align = { light = 2, order = -1 } }, home = "sentinel_hill" },
    { id = "human_dalaran_stray", name = "Student cast out of Dalaran", class = "MAGE",
      blurb = "I was sent to Dalaran as a child and was still there when the demon Archimonde razed it. The city is rebuilding now and slow to open its gates, so I study in Stormwind with the other strays the Kirin Tor left outside.",
