    { id = "human_raven_hill_gravedigger", name = "Gravedigger of Raven Hill", class = "WARLOCK",
      blurb = "I dug graves at Raven Hill and listened to what whispered from them. A book someone left in the crypt taught me that the whispers could be bargained with, and I always keep my side of a bargain.",
      nudge = { trait = { cruel = 1 }, align = { light = -1, honor = 1 } }, home = "darkshire" },
    { id = "human_elwynn_beater", name = "Beater on the nobles' hunts in Elwynn", class = "HUNTER",
      blurb = "I flushed deer and boar out of Elwynn Forest so that lords could shoot them from the saddle. One autumn I kept the best boar for myself, and I've been hunting on my own account ever since.",
      nudge = { trait = { witty = 1 }, align = { order = -2 } }, home = "goldshire" },
    { id = "other", name = "Other" },
  },
}
